12:// ---------------------------------------------------------------------------
13:// Internal helpers
14:// ---------------------------------------------------------------------------
15:
16:/**
17: * Extract the root domain from a URL string.
18: * Returns "" for non-http(s) URLs or on parse failure.
19: */
20:function extractDomain(url) {
21:  if (!url) return "";
22:  try {
23:    const { hostname } = new URL(url);
24:    // Strip leading "www."
25:    return hostname.replace(/^www\./, "");
26:  } catch (_) {
27:    return "";
28:  }
29:}
30:
31:/**
32: * Fuzzy score â€” returns a value 0â€“1.
33: *
34: * Rules (case-insensitive):
35: *   1. Exact substring match                         â†’ 1.0
36: *   2. All query chars appear in order (subsequence) â†’ 0.3â€“0.7, scaled by compactness
37: *   3. No match                                      â†’ 0
38: *
39: * "Compactness" = how short the matched span is relative to the text length.
40: * A perfectly compact match (every char adjacent) scores 0.7;
41: * a very spread-out match floors at 0.3.
42: */
43:function fuzzyScore(query, text) {
44:  if (!query || !text) return 0;
45:
46:  const q = query.toLowerCase();
47:  const t = text.toLowerCase();
48:
49:  // 1. Exact substring
50:  if (t.includes(q)) return 1.0;
51:
52:  // 2. Subsequence match
53:  let qi = 0;
54:  let firstMatch = -1;
55:  let lastMatch = -1;
56:
57:  for (let ti = 0; ti < t.length && qi < q.length; ti++) {
58:    if (t[ti] === q[qi]) {
59:      if (firstMatch === -1) firstMatch = ti;
60:      lastMatch = ti;
61:      qi++;
62:    }
63:  }
64:
65:  if (qi < q.length) return 0; // not all chars found
66:
67:  const span = lastMatch - firstMatch + 1;
68:  // Compactness ratio: ideal span == q.length, worst == t.length
69:  const compactness = q.length / span;
70:  // Map compactness [0,1] â†’ score [0.3, 0.7]
71:  return 0.3 + compactness * 0.4;
72:}
