91: * Returns "" if the tab has no assignment or if workspace data is unavailable.
92: */
93:async function resolveWorkspaceName(tabId) {
94:  try {
95:    const result = await chrome.storage.local.get(WORKSPACE_KEY);
96:    const data = result[WORKSPACE_KEY];
97:    return workspaceNameFromData(tabId, data);
98:  } catch (_) {
99:    return "";
100:  }
101:}
