111:/**
112: * Build a TabEntry from a Chrome Tab object.
113: * metaDescription and headings start empty; they are filled asynchronously
114: * by the content-script injection.
115: */
116:async function buildEntry(tab, existingEntry) {
117:  const domain = extractDomain(tab.url);
118:  const workspaceName = await resolveWorkspaceName(tab.id);
119:
120:  return {
121:    tabId: tab.id,
122:    title: tab.title ?? existingEntry?.title ?? "",
123:    url: tab.url ?? existingEntry?.url ?? "",
124:    domain,
125:    metaDescription: existingEntry?.metaDescription ?? "",
126:    headings: existingEntry?.headings ?? "",
127:    workspaceName,
128:    lastActive: existingEntry?.lastActive ?? Date.now(),
129:  };
130:}
