132:/**
133: * Inject a one-shot content script to extract meta description and headings.
134: * Updates the index entry in storage on success.
135: * Silently ignores privileged URLs and injection errors.
136: */
137:async function injectMetaExtractor(tabId) {
138:  try {
139:    const results = await chrome.scripting.executeScript({
140:      target: { tabId },
141:      func: () => ({
142:        metaDescription:
143:          document.querySelector('meta[name="description"]')?.content ?? "",
144:        headings: [...document.querySelectorAll("h1,h2")]
145:          .map((el) => el.textContent.trim())
146:          .join(" "),
147:      }),
148:    });
149:
150:    const payload = results?.[0]?.result;
151:    if (!payload) return;
152:
153:    await mutateStorageValue(INDEX_KEY, {}, (index) => {
154:      if (!index[tabId]) return;
155:      index[tabId].metaDescription = payload.metaDescription;
156:      index[tabId].headings = payload.headings;
157:    });
158:  } catch (_) {
159:    // Privileged URLs (chrome://, chrome-extension://, about:, etc.) throw here.
160:    // Intentionally swallowed â€” leave metaDescription/headings as "".
161:  }
162:}
