164:/**
165: * initTabIndex â€” wire up Chrome tab event listeners for index maintenance.
166: * Call once from background.js at startup.
167: */
168:export function initTabIndex() {
169:  chrome.storage.onChanged.addListener(async (changes, areaName) => {
170:    if (areaName !== "local" || !changes[WORKSPACE_KEY]) return;
171:    const workspaceData = changes[WORKSPACE_KEY].newValue;
172:    try {
173:      await mutateStorageValue(INDEX_KEY, {}, (index) => {
174:        for (const entry of Object.values(index)) {
175:          entry.workspaceName = workspaceNameFromData(
176:            entry.tabId,
177:            workspaceData,
178:          );
179:        }
180:      });
181:    } catch (_) {}
182:  });
183:
184:  // New tab created
185:  chrome.tabs.onCreated.addListener(async (tab) => {
186:    try {
187:      await mutateStorageValue(INDEX_KEY, {}, async (index) => {
188:        index[tab.id] = await buildEntry(tab, index[tab.id]);
189:      });
190:    } catch (_) {}
191:  });
192:
193:  // Tab updated (title change or navigation complete)
194:  chrome.tabs.onUpdated.addListener(async (tabId, changeInfo, tab) => {
195:    if (changeInfo.status !== "complete" && !changeInfo.title) return;
196:
197:    try {
198:      await mutateStorageValue(INDEX_KEY, {}, async (index) => {
199:        index[tabId] = await buildEntry(tab, index[tabId]);
200:      });
201:    } catch (_) {
202:      return;
203:    }
204:
205:    if (changeInfo.status === "complete") {
206:      await injectMetaExtractor(tabId);
207:    }
208:  });
209:
210:  // Tab activated â€” update lastActive timestamp
211:  chrome.tabs.onActivated.addListener(async (activeInfo) => {
212:    try {
213:      await mutateStorageValue(INDEX_KEY, {}, (index) => {
214:        if (index[activeInfo.tabId]) {
215:          index[activeInfo.tabId].lastActive = Date.now();
216:        }
217:      });
218:    } catch (_) {}
219:  });
220:
221:  // Tab removed â€” delete from index
222:  chrome.tabs.onRemoved.addListener(async (tabId) => {
223:    try {
224:      await mutateStorageValue(INDEX_KEY, {}, (index) => {
225:        delete index[tabId];
226:      });
227:    } catch (_) {}
228:  });
229:}
