231:/**
232: * rebuildIndex â€” query all current tabs and rebuild the index from scratch.
233: * Call once at service-worker startup to handle tabs open before the extension loaded.
234: */
235:export async function rebuildIndex() {
236:  const tabs = await chrome.tabs.query({});
237:  // Seed from the existing index so entries written by the event listeners
238:  // (registered synchronously before this runs) â€” plus already-extracted
239:  // metadata and lastActive values â€” are preserved rather than overwritten.
240:  await mutateStorageValue(INDEX_KEY, {}, async (index) => {
241:    const rebuiltEntries = await Promise.all(
242:      tabs.map(async (tab) => [tab.id, await buildEntry(tab, index[tab.id])]),
243:    );
244:    for (const [tabId, entry] of rebuiltEntries) {
245:      index[tabId] = entry;
246:    }
247:  });
248:
249:  for (const tab of tabs) {
250:    if (tab.status === "complete") {
251:      injectMetaExtractor(tab.id);
252:    }
253:  }
254:}
