260:/**
261: * Compute a weighted fuzzy score for a tab entry against a query string.
262: * Weights: title Ã—3, workspaceName Ã—2, domain Ã—1.5, url Ã—1, metadata Ã—0.5
263: */
264:function scoreTabEntry(query, entry) {
265:  const titleScore = fuzzyScore(query, entry.title) * 3;
266:  const wsScore = fuzzyScore(query, entry.workspaceName) * 2;
267:  const domainScore = fuzzyScore(query, entry.domain) * 1.5;
268:  const urlScore = fuzzyScore(query, entry.url) * 1;
269:  const metadataScore =
270:    Math.max(
271:      fuzzyScore(query, entry.metaDescription),
272:      fuzzyScore(query, entry.headings),
273:    ) * 0.5;
274:  const maxPossible = 3 + 2 + 1.5 + 1 + 0.5; // 8.0
275:  const raw =
276:    titleScore + wsScore + domainScore + urlScore + metadataScore;
277:  return raw / maxPossible; // normalise to 0â€“1
278:}
