296:/**
297: * search(query) â€” run a cross-source search across tabs, bookmarks, and history.
298: *
299: * @param {string} query
300: * @param {string} scope
301: * @param {{ tabs?: boolean, bookmarks?: boolean, history?: boolean }} sources
302: * @returns {Promise<{ tabs: ResultItem[], bookmarks: ResultItem[], history: ResultItem[] }>}
303: */
304:export async function search(
305:  query,
306:  scope = "all",
307:  sources = { tabs: true, bookmarks: false, history: false },
308:) {
309:  const trimmed = query?.trim() ?? "";
310:  if (!trimmed && scope === "all") {
311:    return { tabs: [], bookmarks: [], history: [] };
312:  }
313:
314:  const [tabs, bookmarks, history] = await Promise.all([
315:    scope === "all" && sources.tabs ? searchTabs(trimmed) : [],
316:    (scope === "all" || scope === "bookmarks") && sources.bookmarks
317:      ? searchBookmarks(trimmed)
318:      : [],
319:    (scope === "all" || scope === "history") && sources.history
320:      ? searchHistory(trimmed)
321:      : [],
322:  ]);
323:
324:  return { tabs, bookmarks, history };
325:}
