327:/**
328: * Search open tabs using the local index.
329: */
330:async function searchTabs(query) {
331:  const index = await readIndex();
332:  const entries = Object.values(index);
333:
334:  const scored = entries
335:    .map((entry) => ({
336:      entry,
337:      score: scoreTabEntry(query, entry),
338:    }))
339:    .filter(({ score }) => score > 0.1)
340:    .sort((a, b) => {
341:      if (b.score !== a.score) return b.score - a.score;
342:      return (b.entry.lastActive ?? 0) - (a.entry.lastActive ?? 0);
343:    })
344:    .slice(0, 20);
345:
346:  return scored.map(({ entry, score }) => ({
347:    tabId: entry.tabId,
348:    title: entry.title,
349:    url: entry.url,
350:    favicon: faviconUrl(entry.url),
351:    domain: entry.domain,
352:    context: entry.workspaceName,
353:    score,
354:  }));
355:}
