357:/**
358: * Search bookmarks using the Chrome Bookmarks API.
359: */
360:async function searchBookmarks(query) {
361:  let nodes;
362:  try {
363:    if (query) {
364:      nodes = await chrome.bookmarks.search({ query });
365:    } else {
366:      const roots = await chrome.bookmarks.getTree();
367:      nodes = [];
368:      const visit = (node) => {
369:        if (node.url) nodes.push(node);
370:        node.children?.forEach(visit);
371:      };
372:      roots.forEach(visit);
373:    }
374:  } catch (_) {
375:    return [];
376:  }
377:
378:  // Filter to items that have a URL (not folders)
379:  const bookmarkNodes = nodes.filter((n) => n.url);
380:
381:  // Fetch parent folder names in parallel
382:  const results = await Promise.all(
383:    bookmarkNodes.map(async (node) => {
384:      let context = "";
385:      if (node.parentId) {
386:        try {
387:          const parents = await chrome.bookmarks.get(node.parentId);
388:          context = parents?.[0]?.title ?? "";
389:        } catch (_) {
390:          // ignore
391:        }
392:      }
393:
394:      const domain = extractDomain(node.url);
395:      const titleScore = query ? fuzzyScore(query, node.title ?? "") : 1;
396:      const urlScore = query ? fuzzyScore(query, node.url ?? "") : 1;
397:      const score = Math.max(titleScore, urlScore);
398:
399:      return {
400:        tabId: null,
401:        title: node.title ?? "",
402:        url: node.url ?? "",
403:        favicon: faviconUrl(node.url),
404:        domain,
405:        context,
406:        score,
407:      };
