1:import { mutateStorageValue } from "./storageMutationQueue.js";
2:
3:const PREFIX = "thumb_";
4:const ACCESS_KEY = "thumbnailCacheAccess";
5:const MAX_ENTRIES = 200;
6:const MAX_BYTES = 50 * 1024 * 1024;
7:
8:function dataUrlBytes(value) {
9:  return typeof value === "string" ? value.length : 0;
10:}
11:
12:async function pruneThumbnails(incomingKey, incomingDataUrl) {
13:  await mutateStorageValue(ACCESS_KEY, {}, async (access) => {
14:    access[incomingKey] = {
15:      t: Date.now(),
16:      b: dataUrlBytes(incomingDataUrl),
17:    };
18:    const entries = Object.entries(access)
19:      .map(([key, metadata]) => ({
20:        key,
21:        timestamp: typeof metadata === "number" ? metadata : metadata?.t ?? 0,
22:        bytes: typeof metadata === "number" ? 0 : metadata?.b ?? 0,
23:      }))
24:      .sort((a, b) => a.timestamp - b.timestamp);
25:
26:    let totalBytes = entries.reduce((total, entry) => total + entry.bytes, 0);
27:    const remove = [];
28:    while (
29:      entries.length - remove.length > MAX_ENTRIES ||
30:      totalBytes > MAX_BYTES
31:    ) {
32:      const entry = entries[remove.length];
33:      if (!entry || entry.key === incomingKey) break;
34:      remove.push(entry.key);
35:      totalBytes -= entry.bytes;
36:      delete access[entry.key];
37:    }
38:
39:    if (remove.length) await chrome.storage.local.remove(remove);
40:    await chrome.storage.local.set({ [incomingKey]: incomingDataUrl });
41:    return access;
42:  });
43:}
