7:const DB_NAME = "meridian";
8:const DB_VERSION = 1;
9:const STORE = "backgrounds";
10:const KEY = "custom";
11:const LEGACY_KEY = "meridian_bg_custom";
12:
13:let cachedObjectUrl = null;
14:
15:function openDb() {
16:  return new Promise((resolve, reject) => {
17:    const req = indexedDB.open(DB_NAME, DB_VERSION);
18:    req.onupgradeneeded = () => {
19:      const db = req.result;
20:      if (!db.objectStoreNames.contains(STORE)) db.createObjectStore(STORE);
21:    };
22:    req.onsuccess = () => resolve(req.result);
23:    req.onerror = () => reject(req.error);
24:  });
25:}
26:
27:function idbPut(blob) {
28:  return openDb().then(
29:    (db) =>
30:      new Promise((resolve, reject) => {
31:        const tx = db.transaction(STORE, "readwrite");
32:        tx.objectStore(STORE).put(blob, KEY);
33:        tx.oncomplete = () => {
34:          db.close();
35:          resolve();
36:        };
37:        tx.onerror = () => {
38:          db.close();
39:          reject(tx.error);
40:        };
41:      }),
42:  );
43:}
44:
45:function idbGet() {
46:  return openDb().then(
47:    (db) =>
48:      new Promise((resolve, reject) => {
49:        const tx = db.transaction(STORE, "readonly");
50:        const req = tx.objectStore(STORE).get(KEY);
51:        req.onsuccess = () => {
52:          db.close();
53:          resolve(req.result ?? null);
54:        };
55:        req.onerror = () => {
56:          db.close();
57:          reject(req.error);
58:        };
59:      }),
60:  );
61:}
