79:// Returns a URL usable directly in CSS `url(...)`, or null if none is stored.
80:// The returned `blob:` URL stays valid for the life of the document; the
81:// previous one is revoked so we don't leak object URLs across replacements.
82:export async function getCustomBackgroundUrl() {
83:  const blob = await idbGet();
84:  if (blob) {
85:    if (cachedObjectUrl) URL.revokeObjectURL(cachedObjectUrl);
86:    cachedObjectUrl = URL.createObjectURL(blob);
87:    return cachedObjectUrl;
88:  }
89:  // Legacy fallback: small images uploaded before the IndexedDB move were
90:  // stored as data URLs. Read them so existing backgrounds still render.
91:  try {
92:    const local = await chrome.storage.local.get(LEGACY_KEY);
93:    if (local[LEGACY_KEY] != null) return local[LEGACY_KEY];
94:  } catch {
95:    /* ignore */
96:  }
97:  try {
98:    return localStorage.getItem(LEGACY_KEY);
99:  } catch {
100:    return null;
101:  }
