1:/**
2: * Open a URL from Meridian without destroying the pinned dashboard.
3: *
4: * A pinned Meridian tab is persistent, so launches open beside it. An
5: * unpinned Meridian page is a disposable New Tab instance, so it navigates in
6: * place. If Chrome cannot identify the current tab, opening a new tab is the
7: * safest fallback.
8: */
9:export async function openUrlFromMeridian(url, tabs = chrome.tabs) {
10:  if (!url) return null;
11:
12:  let currentTab = null;
13:  try {
14:    currentTab = await tabs.getCurrent();
15:  } catch {
16:    // Fall through to a new tab if this page has no readable tab context.
17:  }
18:
19:  if (currentTab?.pinned !== true && currentTab?.id != null) {
20:    return tabs.update(currentTab.id, { url });
21:  }
22:
23:  return tabs.create({ url });
24:}

