12:function normalizeWorkspaceData(data) {
13:  if (!data || data.version !== SCHEMA_VERSION) {
14:    return structuredClone(DEFAULT_DATA);
15:  }
16:  if (!data.workspaces.find((w) => w.id === "unsorted")) {
17:    data.workspaces.unshift({ id: "unsorted", name: "Unsorted" });
