22:function mutateWorkspaceData(mutate) {
23:  return mutateStorageValue(STORAGE_KEY, DEFAULT_DATA, (data) => {
24:    data = normalizeWorkspaceData(data);
25:    mutate(data);
26:    return data;
27:  });
