30:export async function getWorkspaceData() {
31:  // Pure read: normalize in memory only. Writing here would fire
32:  // storage.onChanged("workspaces") on every render() call, which the
33:  // meridian.js listener turns back into scheduleRender() â€” a self-sustaining
34:  // render/write loop. Schema migration is persisted lazily by the first
35:  // actual mutation via mutateWorkspaceData().
36:  const result = await chrome.storage.local.get(STORAGE_KEY);
37:  return normalizeWorkspaceData(result[STORAGE_KEY]);
